from datetime import datetime

def parse_dt(s):
    if s is None:
        return None
    try:
        return datetime.fromisoformat(s.replace('Z','+00:00'))
    except Exception:
        return None

candidates = []
for pr in all_requests:
    rname = (pr.get('receiver',{}) or {}).get('name','') or ''
    remail = (pr.get('receiver',{}) or {}).get('email','') or ''
    if 'cory' in rname.lower() or 'cory' in remail.lower():
        candidates.append(pr)

print('candidate_count', len(candidates))
for pr in sorted(candidates, key=lambda x: parse_dt(x.get('approved_at')) or parse_dt(x.get('updated_at')) or parse_dt(x.get('created_at')) or datetime.min, reverse=True)[:10]:
    print({
        'payment_request_id': pr.get('payment_request_id'),
        'amount': pr.get('amount'),
        'receiver_name': pr.get('receiver',{}).get('name'),
        'receiver_email': pr.get('receiver',{}).get('email'),
        'approved_at': pr.get('approved_at'),
        'created_at': pr.get('created_at')
    })

# pick last by approved_at then created_at
best = None
best_dt = None
for pr in candidates:
    dt = parse_dt(pr.get('approved_at')) or parse_dt(pr.get('created_at'))
    if best is None or (dt is not None and best_dt is not None and dt>best_dt) or (best_dt is None and dt is not None):
        best = pr
        best_dt = dt
print('best_selected', {
    'payment_request_id': best.get('payment_request_id'),
    'amount': best.get('amount'),
    'receiver_name': best.get('receiver',{}).get('name'),
    'receiver_email': best.get('receiver',{}).get('email'),
    'approved_at': best.get('approved_at'),
    'created_at': best.get('created_at'),
    'best_dt': best_dt.isoformat() if best_dt else None
})
